From 34c9bb4e974211d529eb1000d976ef8d87d718f9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 13:39:38 +0100
Subject: [PATCH] applets/kickoff: keep hover working while scrolling

Hover was turned off for 200 ms after each wheel event so scrolling over
the sidebar wouldn't switch categories, but that left app lists on a
stale item and made the hovered category blink. Only delay the switch.

BUG: 509188
---
 .../kickoff/AbstractKickoffItemDelegate.qml   | 20 ++++++++++++++-----
 1 file changed, 15 insertions(+), 5 deletions(-)

diff --git a/applets/kickoff/AbstractKickoffItemDelegate.qml b/applets/kickoff/AbstractKickoffItemDelegate.qml
index bc4fcbae6c..23b0c2cf2e 100644
--- a/applets/kickoff/AbstractKickoffItemDelegate.qml
+++ b/applets/kickoff/AbstractKickoffItemDelegate.qml
@@ -197,9 +197,6 @@ T.ItemDelegate {
         anchors.leftMargin: root.view instanceof ListView ? -root.view.leftMargin : anchors.margins
         anchors.rightMargin: root.view instanceof ListView ? -root.view.rightMargin : anchors.margins
         hoverEnabled: root.view
-            // When the movedWithWheel condition is broken, this ensures that
-            // onEntered is called again without moving the mouse.
-            && !root.view.movedWithWheel
             // Fix VerticalStackView animation causing view currentIndex
             // to change while delegates are moving under the mouse cursor
             && kickoff.fullRepresentationItem && !kickoff.fullRepresentationItem.contentItem.busy && !kickoff.fullRepresentationItem.blockingHoverFocus
@@ -209,9 +206,10 @@ T.ItemDelegate {
             // - When the movedWithKeyboard condition is broken, we do not want to
             //   select the hovered item without moving the mouse.
             // - Don't highlight separators.
-            // - Don't switch category items on hover if the setting isn't enabled
+            // - Don't switch category items on hover if the setting isn't enabled,
+            //   or while scrolling over them
             if (root.view.movedWithKeyboard || root.isSeparator
-                || (root.isCategoryListItem && !Plasmoid.configuration.switchCategoryOnHover)) {
+                || (root.isCategoryListItem && (!Plasmoid.configuration.switchCategoryOnHover || root.view.movedWithWheel))) {
                 return
             }

@@ -242,6 +240,18 @@ T.ItemDelegate {
             }
         }

+        // When the movedWithWheel condition is broken, select the hovered
+        // category without moving the mouse.
+        Connections {
+            target: root.view
+            enabled: root.isCategoryListItem && mouseArea.containsMouse
+            function onMovedWithWheelChanged(): void {
+                if (!root.view.movedWithWheel) {
+                    mouseArea.entered()
+                }
+            }
+        }
+
         TapHandler {
             acceptedDevices: PointerDevice.TouchScreen
             onLongPressed: root.openActionMenu(point.position.x, point.position.y)
-- 
2.53.0

